 const students=raw.map((r,i)=>({id:'s'+i,name:r[0],email:r[1],year:r[2],type:r[3],status:r[4],company:r[5],city:r[6],tutor:r[7],supervisor:r[8],supervisorName:r[8]?'Marie Dubois':'',archived:false,cras:[],visits:[],crv:{bilan:'',files:[],amendments:[],visas:[],dispute:false,closed:false},messages:[]}));
