function account(email){return data.accounts.find(a=>a.email===email)}
function person(email){return account(email)?.name||email||'Non affecté'}
function notify(targets,text){const seen=new Set();for(const target of targets.filter(Boolean)){const email=typeof target==='string'?target:target.email;const a=account(email);const r=typeof target==='string'?(a?.roles.includes('student')?'student':a?.roles.includes('company')?'company':a?.roles.includes('tutor')?'tutor':'coordinator'):target.role;const key=email+'|'+r;if(!email||seen.has(key))continue;seen.add(key);data.notifications.unshift({id:id(),email,role:r,text,date:dateTime(),read:false})}}
function audit(text){data.audit.unshift({date:dateTime(),actor:person(session),text})}
function visibleStudents(){return data.students.filter(s=>!s.archived&&(role==='coordinator'||(role==='tutor'&&s.tutor===session)||(role==='student'&&s.email===session)||(role==='company'&&s.supervisor===session)))}
function allowedStudent(s){return !!s&&visibleStudents().some(x=>x.id===s.id)}
