function shell(){const a=account(session);if(!a||a.archived||!a.roles.includes(role)){session=null;role=null;return login()}const unread=data.notifications.filter(n=>n.email===session&&n.role===role&&!n.read).length;const items=nav[role];app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">M</div><div class="brand-text"><strong>suivi<span style="color:#2d78ad">miage</span></strong><small>UNIVERSITÉ DE PICARDIE</small></div></div><div class="sidebar-role">RÔLE ACTIF<strong>${esc(roles[role])}</strong></div><div class="side-scroll"><div class="side-label">ESPACE DE TRAVAIL</div>${items.map(([p,n,i])=>`<button class="nav-btn ${page===p?'active':''}" data-nav="${p}">${icon(i)}<span>${esc(n)}</span></button>`).join('')}<div class="side-label">VOTRE ESPACE</div><button class="nav-btn" data-action="guide">${icon('switch')}<span>Guide démo</span></button><button class="nav-btn" data-action="logout">${icon('logout')}<span>Se déconnecter</span></button></div><div class="side-bottom"><div class="side-person"><div class="avatar">${esc(initials(a.name))}</div><div><strong>${esc(a.name)}</strong><small>${esc(roles[role])}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><span>Espace MIAGE</span><span>/</span><b>${esc(items.find(n=>n[0]===page)?.[1]||'Dossier étudiant')}</b></div><div class="top-actions"><div class="top-role">Rôle actif <b>${esc(roles[role])}</b></div><button class="btn sm" data-action="guide">${icon('switch',14)} Guide démo / Switch</button><button class="icon-btn" data-action="notifications" title="Notifications" aria-label="Notifications">${icon('bell',17)}${unread?'<span class="badge-dot"></span>':''}</button><div class="avatar" title="${esc(a.name)}">${esc(initials(a.name))}</div></div></header><div class="content">${renderPage()}</div></main></div>${renderModal()}`}
function login(){app.innerHTML=`<div class="login"><div class="login-left"><div class="brand" style="padding:0;color:white"><div class="brand-mark" style="background:#fff;color:#002e5a">M</div><div><strong>suivimiage</strong><small style="color:#a9c8dc">UNIVERSITÉ DE PICARDIE</small></div></div><div><div class="eyebrow" style="color:#9fc6dd">STAGES & ALTERNANCES</div><h1>Un suivi plus clair,<br>à chaque étape.</h1><p>Un espace partagé pour accompagner les étudiants, les équipes pédagogiques et les entreprises tout au long de leur parcours.</p></div><p style="font-size:11px">Prototype de démonstration · Données fictives uniquement</p></div><div class="login-right"><div class="login-box"><div class="eyebrow">BIENVENUE SUR SUIVI MIAGE</div><h2>Connexion</h2><p class="section-desc">Choisissez un compte de démonstration pour continuer.</p><form class="form" id="login-form"><div class="field"><label for="login-email">Adresse e-mail</label><input class="input" type="email" id="login-email" required></div><div class="field"><label for="login-password">Mot de passe de démonstration</label><input class="input" type="password" id="login-password" required value="demo"></div><button class="btn primary" type="submit">Se connecter ${icon('arrow',15)}</button></form><p class="subtle" style="margin-top:20px">COMPTES DE DÉMONSTRATION · MOT DE PASSE : demo</p><div class="account-options">${data.accounts.filter(a=>(['camille@demo.miage.fr','noe@demo.miage.fr','laurent@demo.miage.fr','sarah@demo.miage.fr','nadia@demo.miage.fr','admin@demo.miage.fr'].includes(a.email)||a.roles.includes('company'))&&!a.archived).map(a=>`<button class="account-option" data-login="${esc(a.email)}"><b>${esc(a.name)}</b><small>${esc(a.roles.map(r=>roles[r]).join(' / '))}</small></button>`).join('')}</div><p class="subtle" style="margin-top:20px">Démo locale : aucune authentification réelle, n’utilisez pas de données personnelles.</p></div></div></div>${renderModal()}`}
function render(){if(session&&role)shell();else login()}
function filtered(){return data.students.filter(s=>!s.archived&&(!filters.year||s.year===filters.year)&&(!filters.type||s.type===filters.type)&&(!filters.status||s.status===filters.status)&&(!filters.place||`${s.company} ${s.city}`.toLowerCase().includes(filters.place.toLowerCase()))&&(!filters.search||`${s.name} ${s.company} ${s.city} ${person(s.tutor)}`.toLowerCase().includes(filters.search.toLowerCase()))).sort((a,b)=>String(sort.key==='tutor'?person(a.tutor):a[sort.key]||'').localeCompare(String(sort.key==='tutor'?person(b.tutor):b[sort.key]||''),'fr')*sort.dir)}
