function cohortTable(list,open=false){list=[...list].sort((a,b)=>String(sort.key==='tutor'?person(a.tutor):a[sort.key]||'').localeCompare(String(sort.key==='tutor'?person(b.tutor):b[sort.key]||''),'fr')*sort.dir);return `<div class="table-wrap"><table><thead><tr>${[['name','Étudiant'],['year','Promotion'],['type','Type de contrat'],['company','Entreprise'],['city','Ville'],['tutor','Tuteur universitaire'],['status','Statut']].map(([k,l])=>`<th><button data-sort="${k}" title="Trier par ${l}">${l}${sort.key===k?(sort.dir===1?' ↑':' ↓'):''}</button></th>`).join('')}${open?'<th>Dossier</th>':''}</tr></thead><tbody>${list.map(s=>`<tr><td><div class="table-name"><span class="initial">${esc(initials(s.name))}</span><strong>${esc(s.name)}</strong></div></td><td>${esc(s.year)}</td><td>${esc(s.type)}</td><td>${esc(s.company||'—')}</td><td>${esc(s.city||'—')}</td><td>${esc(person(s.tutor))}</td><td>${badge(s.status)}</td>${open?`<td><button class="btn sm" data-open="${s.id}">Ouvrir ${icon('arrow',13)}</button></td>`:''}</tr>`).join('')||'<tr><td colspan="8" class="empty">Aucun dossier ne correspond aux filtres.</td></tr>'}</tbody></table></div>`}
