 const tutorEmails=Object.keys(data.settings.capacity),loads=tutorEmails.map(t=>[person(t),list.filter(s=>s.tutor===t).length,data.settings.capacity[t]]),mean=loads.length?(loads.reduce((n,l)=>n+l[1],0)/loads.length).toFixed(1).replace('.',','):'0';
 const counts=types.map(t=>list.filter(s=>s.type===t).length),colors=['#236d9d','#64a7cb','#d9a45e'];
